<?php

declare(strict_types=1);

namespace App\Domains\Assessment\Infrastructure\Models;

use App\Traits\HasSchoolId;
use Illuminate\Database\Eloquent\Factories\Factory;
use Illuminate\Database\Eloquent\Factories\HasFactory;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Database\Eloquent\SoftDeletes;

/**
 * Persisted aggregate statistics of an assessment (SPR-009). Generated by
 * GenerateAssessmentStatisticsAction, never written by hand.
 */
class AssessmentStatistics extends Model
{
    use HasFactory;
    use HasSchoolId;
    use SoftDeletes;

    protected $table = 'assessment_statistics';

    protected $fillable = [
        'uuid',
        'school_id',
        'assessment_id',
        'total_scores',
        'average',
        'minimum',
        'maximum',
        'median',
        'pass_rate',
        'completion_rate',
        'generated_at',
        'generated_by',
    ];

    protected function casts(): array
    {
        return [
            'total_scores' => 'integer',
            'average' => 'float',
            'minimum' => 'float',
            'maximum' => 'float',
            'median' => 'float',
            'pass_rate' => 'float',
            'completion_rate' => 'float',
            'generated_at' => 'datetime',
        ];
    }

    protected static function newFactory(): Factory
    {
        return new \Database\Factories\Assessment\AssessmentStatisticsFactory();
    }

    public function assessment(): BelongsTo
    {
        return $this->belongsTo(Assessment::class, 'assessment_id');
    }
}
